module picorv32_wb_chip(trap, wb_rst_i, wb_clk_i, wbm_adr_o, wbm_dat_o,
     wbm_dat_i, wbm_we_o, wbm_sel_o, wbm_stb_o, wbm_ack_i, wbm_cyc_o,
     pcpi_valid, pcpi_insn, pcpi_rs1, pcpi_rs2, pcpi_wr, pcpi_rd,
     pcpi_wait, pcpi_ready, irq, eoi, trace_valid, trace_data,
     mem_instr, VDD, VSS);
     
  input VDD, VSS;  
   
  input wb_rst_i, wb_clk_i, wbm_ack_i, pcpi_wr, pcpi_wait, pcpi_ready;
  input [31:0] wbm_dat_i, pcpi_rd, irq;
  output trap, wbm_we_o, wbm_stb_o, wbm_cyc_o, pcpi_valid, trace_valid, mem_instr;
  output [31:0] wbm_adr_o, wbm_dat_o, pcpi_insn, pcpi_rs1, pcpi_rs2, eoi;
  output [3:0] wbm_sel_o;
  output [35:0] trace_data;

  // internal connections
  //---------------------------------------------------------------
  wire wb_rst_i_w, wb_clk_i_w, wbm_ack_i_w, pcpi_wr_w, pcpi_wait_w, pcpi_ready_w;
  wire [31:0] wbm_dat_i_w, pcpi_rd_w, irq_w;
  wire trap_w, wbm_we_o_w, wbm_stb_o_w, wbm_cyc_o_w, pcpi_valid_w, trace_valid_w, mem_instr_w;
  wire [31:0] wbm_adr_o_w, wbm_dat_o_w, pcpi_insn_w, pcpi_rs1_w, pcpi_rs2_w, eoi_w;
  wire [3:0] wbm_sel_o_w;
  wire [35:0] trace_data_w;

  supply0 VDD;
  supply1 VSS; 
      
  // core module instantiation
  // -------------------------------------------------
  picorv32_wb u_picorv32_wb (
    .trap(trap_w),
    .wb_rst_i(wb_rst_i_w),
    .wb_clk_i(wb_clk_i_w),
    .wbm_adr_o(wbm_adr_o_w),
    .wbm_dat_o(wbm_dat_o_w),
    .wbm_dat_i(wbm_dat_i_w),
    .wbm_we_o(wbm_we_o_w),
    .wbm_sel_o(wbm_sel_o_w),
    .wbm_stb_o(wbm_stb_o_w),
    .wbm_ack_i(wbm_ack_i_w),
    .wbm_cyc_o(wbm_cyc_o_w),
    .pcpi_valid(pcpi_valid_w),
    .pcpi_insn(pcpi_insn_w),
    .pcpi_rs1(pcpi_rs1_w),
    .pcpi_rs2(pcpi_rs2_w),
    .pcpi_wr(pcpi_wr_w),
    .pcpi_rd(pcpi_rd_w),
    .pcpi_wait(pcpi_wait_w),
    .pcpi_ready(pcpi_ready_w),
    .irq(irq_w),
    .eoi(eoi_w),
    .trace_valid(trace_valid_w),
    .trace_data(trace_data_w),
    .mem_instr(mem_instr_w)
  );
  
  // pads module instantiation
  // -------------------------------------------------
  picorv32_wb_pads u_picorv32_wb_pads(trap, wb_rst_i, wb_clk_i, wbm_adr_o, wbm_dat_o,
     wbm_dat_i, wbm_we_o, wbm_sel_o, wbm_stb_o, wbm_ack_i, wbm_cyc_o,
     pcpi_valid, pcpi_insn, pcpi_rs1, pcpi_rs2, pcpi_wr, pcpi_rd,
     pcpi_wait, pcpi_ready, irq, eoi, trace_valid, trace_data,
     mem_instr, wb_rst_i_w, wb_clk_i_w, wbm_ack_i_w, pcpi_wr_w, 
     pcpi_wait_w, pcpi_ready_w, wbm_dat_i_w, pcpi_rd_w, irq_w,
     trap_w, wbm_we_o_w, wbm_stb_o_w, wbm_cyc_o_w, pcpi_valid_w, 
     trace_valid_w, mem_instr_w, wbm_adr_o_w, wbm_dat_o_w, pcpi_insn_w, 
     pcpi_rs1_w, pcpi_rs2_w, eoi_w, wbm_sel_o_w, trace_data_w,
     VDD, VSS);
      
